vs:"layout(std140) uniform phongMaterialUniforms {\n  uniform bool unlit;\n  uniform float ambient;\n  uniform float diffuse;\n  uniform float shininess;\n  uniform vec3  specularColor;\n} material;\n",fs:"layout(std140) uniform phongMaterialUniforms {\n  uniform bool unlit;\n  uniform float ambient;\n  uniform float diffuse;\n  uniform float shininess;\n  uniform vec3  specularColor;\n} material;\n\nvec3 lighting_getLightColor(vec3 surfaceColor, vec3 light_direction, vec3 view_direction, vec3 normal_worldspace, vec3 color) {\n  vec3 halfway_direction \x3d normalize(light_direction + view_direction);\n  float lambertian \x3d dot(light_direction, normal_worldspace);\n  float specular \x3d 0.0;\n  if (lambertian \x3e 0.0) {\n    float specular_angle \x3d max(dot(normal_worldspace, halfway_direction), 0.0);\n    specular \x3d pow(specular_angle, material.shininess);\n  }\n  lambertian \x3d max(lambertian, 0.0);\n  return (lambertian * material.diffuse * surfaceColor + specular * floatColors_normalize(material.specularColor)) * color;\n}\n\nvec3 lighting_getLightColor(vec3 surfaceColor, vec3 cameraPosition, vec3 position_worldspace, vec3 normal_worldspace) {\n  vec3 lightColor \x3d surfaceColor;\n\n  if (material.unlit) {\n    return surfaceColor;\n  }\n\n  if (lighting.enabled \x3d\x3d 0) {\n    return lightColor;\n  }\n\n  vec3 view_direction \x3d normalize(cameraPosition - position_worldspace);\n  lightColor \x3d material.ambient * surfaceColor * lighting.ambientColor;\n\n  for (int i \x3d 0; i \x3c lighting.pointLightCount; i++) {\n    PointLight pointLight \x3d lighting_getPointLight(i);\n    vec3 light_position_worldspace \x3d pointLight.position;\n    vec3 light_direction \x3d normalize(light_position_worldspace - position_worldspace);\n    float light_attenuation \x3d getPointLightAttenuation(pointLight, distance(light_position_worldspace, position_worldspace));\n    lightColor +\x3d lighting_getLightColor(surfaceColor, light_direction, view_direction, normal_worldspace, pointLight.color / light_attenuation);\n  }\n\n  for (int i \x3d 0; i \x3c lighting.spotLightCount; i++) {\n    SpotLight spotLight \x3d lighting_getSpotLight(i);\n    vec3 light_position_worldspace \x3d spotLight.position;\n    vec3 light_direction \x3d normalize(light_position_worldspace - position_worldspace);\n    float light_attenuation \x3d getSpotLightAttenuation(spotLight, position_worldspace);\n    lightColor +\x3d lighting_getLightColor(surfaceColor, light_direction, view_direction, normal_worldspace, spotLight.color / light_attenuation);\n  }\n\n  for (int i \x3d 0; i \x3c lighting.directionalLightCount; i++) {\n    DirectionalLight directionalLight \x3d lighting_getDirectionalLight(i);\n    lightColor +\x3d lighting_getLightColor(surfaceColor, -directionalLight.direction, view_direction, normal_worldspace, directionalLight.color);\n  }\n  \n  return lightColor;\n}\n",
